269	static void update_wave(void)
270	{
271	  if (!g_anim.wave_canvas)
272	    {
273	      return;
274	    }
275	
276	  int sw = lv_display_get_horizontal_resolution(NULL);
277	  int w = sw - 40;
278	  int h = 120;
279	  int cy = h / 2;
280	
281	  /* Clear canvas with transparent background */
282	
283	  lv_canvas_fill_bg(g_anim.wave_canvas, lv_color_hex(0x000000),
284	                    LV_OPA_TRANSP);
285	
286	  g_anim.wave_phase += 0.08f;
287	
288	  /* Draw multiple sine waves with different colors and phases */
289	
290	  int wave;
291	  for (wave = 0; wave < 3; wave++)
292	    {
293	      uint32_t colors[] = {0x4ECDC4, 0xFF6B6B, 0xFFEAA7};
294	      float phase_offset = wave * 2.094f; /* 2*PI/3 */
295	      float amplitude = 30.0f - wave * 5.0f;
296	
297	      for (int px = 0; px < w - 1; px++)
298	        {
299	          float x1 = (float)px / w * 4.0f * PI;
300	          float x2 = (float)(px + 1) / w * 4.0f * PI;
301	
302	          int y1 = cy + (int)(sinf(x1 + g_anim.wave_phase + phase_offset) *
303	                              amplitude);
304	          int y2 = cy + (int)(sinf(x2 + g_anim.wave_phase + phase_offset) *
305	                              amplitude);
306	
307	          /* Draw line between points using Bresenham's algorithm */
308	
309	          int dx = abs(px + 1 - px);
310	          int dy = abs(y2 - y1);
311	          int sx = px < (px + 1) ? 1 : -1;
312	          int sy = y1 < y2 ? 1 : -1;
313	          int err = dx - dy;
314	          int ex = px;
315	          int ey = y1;
316	
317	          while (1)
318	            {
319	              if (ex >= 0 && ex < w && ey >= 0 && ey < h)
320	                {
321	                  lv_canvas_set_px(g_anim.wave_canvas, ex, ey,
322	                                   lv_color_hex(colors[wave]),
323	                                   LV_OPA_80);
324	                }
325	
326	              if (ex == px + 1 && ey == y2)
327	                {
328	                  break;
329	                }
330	
331	              int e2 = 2 * err;
332	              if (e2 > -dy)
333	                {
334	                  err -= dy;
335	                  ex += sx;
336	                }
337	
338	              if (e2 < dx)
339	                {
340	                  err += dx;
341	                  ey += sy;
342	                }
343	            }
344	        }
345	    }
346	}
