static void card_click_cb(lv_event_t *e)
{
  lv_obj_t *card = lv_event_get_target(e);
  int idx = (int)(intptr_t)lv_event_get_user_data(e);

  if (idx < 0 || idx >= NUM_CATEGORIES)
    {
      return;
    }

  category_t *cat = &g_phy.categories[idx];

  if (cat->expanded)
    {
      /* Collapse */

      if (cat->detail_panel)
        {
          lv_obj_add_flag(cat->detail_panel, LV_FLAG_HIDDEN);
          lv_obj_set_height(cat->card, 72);
        }

      cat->expanded = false;
      g_phy.current_expanded = -1;
    }
  else
    {
      /* Collapse any previously expanded */

      if (g_phy.current_expanded >= 0 &&
          g_phy.current_expanded < NUM_CATEGORIES)
        {
          category_t *prev =
            &g_phy.categories[g_phy.current_expanded];
          if (prev->detail_panel)
            {
              lv_obj_add_flag(prev->detail_panel, LV_FLAG_HIDDEN);
              lv_obj_set_height(prev->card, 72);
            }

          prev->expanded = false;
        }

      /* Expand this one */

      if (cat->detail_panel)
        {
          lv_obj_remove_flag(cat->detail_panel, LV_FLAG_HIDDEN);
          int detail_h = 8 + cat->num_experiments * 36 + 8;
          lv_obj_set_height(cat->card, 72 + detail_h);
        }

      cat->expanded = true;
      g_phy.current_expanded = idx;
    }
}

static void create_category_card(int idx)
{
  int sw = lv_display_get_horizontal_resolution(NULL);
  int card_w = sw - 24;
  category_t *cat = &g_phy.categories[idx];

  /* Card container */

  cat->card = lv_obj_create(g_phy.scroll_cont);
  lv_obj_remove_style_all(cat->card);
  lv_obj_set_size(cat->card, card_w, 72);
  lv_obj_set_style_bg_color(cat->card, lv_color_hex(0x1A1A2E), 0);
  lv_obj_set_style_bg_opa(cat->card, LV_OPA_100, 0);
  lv_obj_set_style_radius(cat->card, 12, 0);
  lv_obj_set_style_pad_all(cat->card, CARD_PADDING, 0);
  lv_obj_set_style_border_color(cat->card, lv_color_hex(0x2A2A4E), 0);
  lv_obj_set_style_border_width(cat->card, 1, 0);
  lv_obj_set_flex_flow(cat->card, LV_FLEX_FLOW_COLUMN);
  lv_obj_set_flex_align(cat->card, LV_FLEX_ALIGN_START,
                         LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);

  /* Top row: icon + name */

  lv_obj_t *top_row = lv_obj_create(cat->card);
  lv_obj_remove_style_all(top_row);
  lv_obj_set_size(top_row, card_w - 2 * CARD_PADDING, 48);
  lv_obj_set_flex_flow(top_row, LV_FLEX_FLOW_ROW);
  lv_obj_set_flex_align(top_row, LV_FLEX_ALIGN_START,
                         LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);

  /* Icon circle */

  lv_obj_t *icon_bg = lv_obj_create(top_row);
  lv_obj_remove_style_all(icon_bg);
  lv_obj_set_size(icon_bg, 44, 44);
  lv_obj_set_style_radius(icon_bg, LV_RADIUS_CIRCLE, 0);
  lv_obj_set_style_bg_color(icon_bg, lv_color_hex(cat->color), 0);
  lv_obj_set_style_bg_opa(icon_bg, LV_OPA_20, 0);
  lv_obj_set_flex_align(icon_bg, LV_FLEX_ALIGN_CENTER,
                         LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);

  lv_obj_t *icon_lbl = lv_label_create(icon_bg);
  lv_label_set_text(icon_lbl, cat->icon);
  lv_obj_set_style_text_color(icon_lbl, lv_color_hex(cat->color), 0);
  lv_obj_set_style_text_font(icon_lbl, &lv_font_montserrat_20, 0);
  lv_obj_center(icon_lbl);

  /* Category name */

  cat->title_label = lv_label_create(top_row);
  lv_label_set_text(cat->title_label, cat->name);
  lv_obj_set_style_text_color(cat->title_label,
                               lv_color_hex(0xEEEEEE), 0);
  lv_obj_set_style_text_font(cat->title_label, &lv_font_montserrat_20, 0);

  /* Arrow indicator */

  lv_obj_t *arrow = lv_label_create(top_row);
  lv_label_set_text(arrow, ">");
  lv_obj_set_style_text_color(arrow, lv_color_hex(0x666666), 0);
  lv_obj_set_style_text_font(arrow, &lv_font_montserrat_16, 0);
  lv_obj_set_style_pad_left(arrow, 0, 0);
  lv_obj_set_flex_grow(arrow, 1);
  lv_obj_set_style_text_align(arrow, LV_TEXT_ALIGN_RIGHT, 0);

  /* Detail panel (hidden initially) */

  cat->detail_panel = lv_obj_create(cat->card);
  lv_obj_remove_style_all(cat->detail_panel);
  int detail_h = 8 + cat->num_experiments * 36 + 8;
  lv_obj_set_size(cat->detail_panel, card_w - 2 * CARD_PADDING, detail_h);
  lv_obj_set_style_pad_all(cat->detail_panel, 8, 0);
  lv_obj_set_flex_flow(cat->detail_panel, LV_FLEX_FLOW_COLUMN);
  lv_obj_set_flex_align(cat->detail_panel, LV_FLEX_ALIGN_START,
                         LV_FLEX_ALIGN_START, LV_FLEX_ALIGN_CENTER);
  lv_obj_add_flag(cat->detail_panel, LV_FLAG_HIDDEN);

  /* Experiment items */

  int i;
  for (i = 0; i < cat->num_experiments; i++)
    {
      const experiment_t *exp = &cat->experiments[i];

      lv_obj_t *row = lv_obj_create(cat->detail_panel);
      lv_obj_remove_style_all(row);
      lv_obj_set_size(row, card_w - 2 * CARD_PADDING - 16, 32);
      lv_obj_set_style_radius(row, 6, 0);
      lv_obj_set_style_bg_color(row, lv_color_hex(0x0F3460), 0);
      lv_obj_set_style_bg_opa(row, LV_OPA_100, 0);
      lv_obj_set_flex_flow(row, LV_FLEX_FLOW_ROW);
      lv_obj_set_flex_align(row, LV_FLEX_ALIGN_START,
                             LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
      lv_obj_set_style_pad_left(row, 8, 0);
      lv_obj_set_style_pad_right(row, 8, 0);

      /* Small colored dot */

      lv_obj_t *dot = lv_obj_create(row);
      lv_obj_remove_style_all(dot);
      lv_obj_set_size(dot, 8, 8);
      lv_obj_set_style_radius(dot, LV_RADIUS_CIRCLE, 0);
      lv_obj_set_style_bg_color(dot, lv_color_hex(exp->color), 0);
      lv_obj_set_style_bg_opa(dot, LV_OPA_100, 0);

      /* Experiment name */

      lv_obj_t *name_lbl = lv_label_create(row);
      lv_label_set_text(name_lbl, exp->name);
      lv_obj_set_style_text_color(name_lbl, lv_color_hex(0xCCCCCC), 0);
      lv_obj_set_style_text_font(name_lbl, &lv_font_montserrat_14, 0);
    }

  cat->expanded = false;

  /* Add click event */

  lv_obj_add_event_cb(cat->card, card_click_cb, LV_EVENT_CLICKED,
                       (void *)(intptr_t)idx);
}

static void create_menu(void)
{
  int sw = lv_display_get_horizontal_resolution(NULL);
  int sh = lv_display_get_vertical_resolution(NULL);
  lv_obj_t *scr = lv_screen_active();

  /* Scrollable container */

  g_phy.scroll_cont = lv_obj_create(scr);
  lv_obj_remove_style_all(g_phy.scroll_cont);
  lv_obj_set_size(g_phy.scroll_cont, sw, sh - 60 - 24);
  lv_obj_align(g_phy.scroll_cont, LV_ALIGN_TOP_MID, 0, 60);
  lv_obj_set_flex_flow(g_phy.scroll_cont, LV_FLEX_FLOW_COLUMN);
  lv_obj_set_flex_align(g_phy.scroll_cont, LV_FLEX_ALIGN_START,
                         LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
  lv_obj_set_style_pad_top(g_phy.scroll_cont, 12, 0);
  lv_obj_set_style_pad_bottom(g_phy.scroll_cont, 12, 0);
  lv_obj_set_style_pad_row(g_phy.scroll_cont, CARD_MARGIN, 0);
  lv_obj_set_scroll_dir(g_phy.scroll_cont, LV_DIR_VER);
  lv_obj_set_scrollbar_mode(g_phy.scroll_cont, LV_SCROLLBAR_MODE_AUTO);

  /* Create category cards */

  int i;
  for (i = 0; i < NUM_CATEGORIES; i++)
    {
      g_phy.categories[i] = g_categories_def[i];
      create_category_card(i);
    }

  g_phy.current_expanded = -1;
}

static void update_fps(void)
{
  g_phy.frame_count++;
  uint32_t now = lv_tick_get();
  uint32_t elapsed = now - g_phy.last_tick;

  if (elapsed >= 1000)
    {
      uint32_t fps = g_phy.frame_count * 1000 / elapsed;
      char buf[64];
      snprintf(buf, sizeof(buf), "FPS: %lu", (unsigned long)fps);
      lv_label_set_text(g_phy.fps_label, buf);
      g_phy.frame_count = 0;
      g_phy.last_tick = now;
    }
}

static void main_timer_cb(lv_timer_t *timer)
{
  update_fps();
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int main(int argc, FAR char *argv[])
{
  lv_nuttx_dsc_t info;
  lv_nuttx_result_t result;

  if (lv_is_initialized())
    {
      LV_LOG_ERROR("LVGL already initialized! aborting.");
      return -1;
    }

#ifdef CONFIG_BOARDCTL
#  ifndef CONFIG_NSH_ARCHINIT
  boardctl(BOARDIOC_INIT, 0);
#  endif
#endif

  lv_init();
  lv_nuttx_dsc_init(&info);

#ifdef CONFIG_LV_USE_NUTTX_LCD
  info.fb_path = "/dev/lcd0";
#endif

#ifdef CONFIG_INPUT_TOUCHSCREEN
  info.input_path = "/dev/input0";
#endif

  lv_nuttx_init(&info, &result);

  if (result.disp == NULL)
    {
      LV_LOG_ERROR("Display initialization failure!");
      return 1;
    }

  /* Dark background */

  lv_obj_set_style_bg_color(lv_screen_active(),
                             lv_color_hex(0x0A0A1A), 0);
  lv_obj_set_style_bg_opa(lv_screen_active(), LV_OPA_100, 0);

  /* Initialize context */

  memset(&g_phy, 0, sizeof(g_phy));
  g_phy.last_tick = lv_tick_get();

  /* Build UI */

  create_header();
  create_menu();
  create_status_bar();

  /* Animation timer */

  lv_timer_create(main_timer_cb, 100, NULL);

  /* Main loop */

  while (1)
    {
      uint32_t idle = lv_timer_handler();
      idle = idle ? idle : 1;
      usleep(idle * 1000);
    }

  return 0;
}

